"""Red-team (TASK-20260929-810095) independent abstract-model library.
Written from the TEXT of EXP-BINSTD-8cb697 (definitions.observables_and_tests,
null_arm, outcome_table) and H-BINSTD-099d93 H1, not from binstd_core's
_mc_* routines. No group, oracle, curve, fixture or declared cell."""
import math, random
from collections import deque

L_IC = (1, 4, 16, 64, 256, 1024)
L_NULL = (1, 4, 16)
L_RHO = (1, 4, 16, 64, 256)
N_T = sum(L_IC)            # 1365 reuse targets
S_DELTA, Z_DELTA, Z_U, Z_A, Z_CMP, Z_AM, Z_YIELD = 0.403, 3.3, 3.0, 3.0, 3.3, 3.5, 3.0
DSIG = 0.10
MAX_ATTEMPTS = 100000

def _delta_inf():
    # root of y = 1 - exp(-2y), bisection (independent of the fixed-point code)
    lo, hi = 0.5, 1.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if mid - (1.0 - math.exp(-2.0 * mid)) < 0: lo = mid
        else: hi = mid
    return 0.5 * (lo + hi)
DELTA_INF = _delta_inf()
U_PRED = DELTA_INF ** 2

def a_pred(mu): return 1.0 / (1.0 - math.exp(-mu * U_PRED))
def A(mu): return 1.0 / (1.0 - math.exp(-mu))
def k_pred(B, mu): return B * A(mu) / a_pred(mu)
def lsq_slope(xs, ys):
    n = len(xs); mx = sum(xs) / n; my = sum(ys) / n
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / sum((x - mx) ** 2 for x in xs)
def sig_pred(K, cells):
    return lsq_slope([math.log2(L) for L in cells], [math.log2(K / L + 1.0) for L in cells])

def bands(B, mu, n_t):
    x = mu * U_PRED; p = 1.0 - math.exp(-x); g = x / (math.exp(x) - 1.0)
    s_lnu = 2.0 * S_DELTA / (math.sqrt(B) * DELTA_INF)
    vfr = (1.0 - p) / n_t + (g * s_lnu) ** 2
    vkr = math.exp(-mu) / B + vfr
    sfr, skr = math.sqrt(vfr), math.sqrt(vkr)
    return {"KR": (math.exp(-Z_AM * skr), math.exp(Z_AM * skr)),
            "FR": (math.exp(-Z_AM * sfr), math.exp(Z_AM * sfr)), "s_lnKR": skr, "s_lnFR": sfr}

# ---- sampling helpers --------------------------------------------------------
def geom(rng, q):
    """trials up to and including the first success, success prob q"""
    if q >= 1.0: return 1
    return 1 + int(math.log(1.0 - rng.random()) / math.log1p(-q))
def poisson(rng, lam):
    if lam <= 0: return 0
    u = rng.random(); k = 0; pk = math.exp(-lam); c = pk
    while u > c and k < 10000:
        k += 1; pk *= lam / k; c += pk
    return k
def ztp(rng, lam):
    """Poisson(lam) conditioned >= 1, by inversion"""
    u = rng.random() * (1.0 - math.exp(-lam))
    k = 1; pk = lam * math.exp(-lam); c = pk
    while u > c and k < 10000:
        k += 1; pk *= lam / k; c += pk
    return k

# ---- determined set by BFS parity analysis (independent of _SignedUF) --------
def determined_set(B, edges):
    """edges: list of (i, s, k, t) meaning s x_i + t x_k = const (s, t in +-1).
    x_i = const + sigma x_k with sigma = -s t. A component is determined iff it
    contains a coefficient-2 loop (i == k, s == t) or an unbalanced cycle."""
    adj = [[] for _ in range(B)]
    loop2 = [False] * B
    touched = [False] * B
    for (i, s, k, t) in edges:
        touched[i] = touched[k] = True
        if i == k:
            if s == t: loop2[i] = True
            continue
        sigma = -s * t
        par = 0 if sigma == 1 else 1
        adj[i].append((k, par)); adj[k].append((i, par))
    comp_par = [-1] * B
    det = [False] * B
    for v in range(B):
        if comp_par[v] != -1: continue
        comp = [v]; comp_par[v] = 0; dq = deque([v]); bad = loop2[v]
        while dq:
            a = dq.popleft()
            for (b, par) in adj[a]:
                want = comp_par[a] ^ par
                if comp_par[b] == -1:
                    comp_par[b] = want; comp.append(b); dq.append(b)
                    if loop2[b]: bad = True
                elif comp_par[b] != want:
                    bad = True
        if bad:
            for c in comp: det[c] = True
    return det, touched

def draw_legs(rng, B):
    while True:
        i, k = rng.randrange(B), rng.randrange(B)
        s, t = (1 if rng.random() < 0.5 else -1), (1 if rng.random() < 0.5 else -1)
        if i == k and s == -t:   # R = 0, impossible for R != 0: resample
            continue
        return i, s, k, t

# ---- one reuse arm ------------------------------------------------------------
def count_dist(rng, mu_true, deficit=None):
    """number of decompositions in an attempt that is NONEMPTY.
    deficit None: ZTP(mu_true). deficit = (kappa_prime, lam): clustered model with
    P(D>=1) = kappa_prime and D | D>=1 = 1 + Poisson(lam) (mean kept by the caller)."""
    if deficit is None: return ztp(rng, mu_true)
    return 1 + poisson(rng, deficit[1])

def reuse_arm(rng, B, mu_c, f=1.0, deficit=None, n_t=N_T):
    mu_true = f * mu_c
    q = (1.0 - math.exp(-mu_true)) if deficit is None else deficit[0]
    rel_att = 0; edges = []
    for _ in range(B):
        rel_att += geom(rng, q)
        edges.append(draw_legs(rng, B))
    det, touched = determined_set(B, edges)
    delta_hat = sum(det) / B
    per_t = []; n_dec = n_use = n_att = n_ne = 0; abandoned = 0
    for L in L_IC:
        for _ in range(L):
            att = ne = nd = nu = 0
            while True:
                att += geom(rng, q)
                if att > MAX_ATTEMPTS:
                    att = MAX_ATTEMPTS; abandoned += 1; break
                ne += 1
                D = count_dist(rng, mu_true, deficit)
                nd += D
                uu = 0
                for _d in range(D):
                    i, s, k, t = draw_legs(rng, B)
                    if det[i] and det[k]: uu += 1
                nu += uu
                if uu: break
            per_t.append((L, att))
            n_dec += nd; n_use += nu; n_att += att; n_ne += ne
    return {"B": B, "mu": mu_c, "rel_att": rel_att, "delta_hat": delta_hat,
            "tau_hat": sum(touched) / B, "u_hat": (n_use / n_dec) if n_dec else 0.0,
            "n_dec": n_dec, "n_att": n_att, "n_t": n_t, "a_bar": n_att / n_t,
            "kappa_hat": n_ne / n_att, "per_t": per_t, "abandoned": abandoned, "edges": edges,
            "det": det}

def null_arm(rng, B, mu_c, f=1.0):
    mu_true = f * mu_c
    q = 1.0 - math.exp(-mu_true)
    check = max(1, B // 16)
    out = []
    for L in L_NULL:
        for _ in range(L):
            t_att = geom(rng, q)
            stored = [(rng.randrange(B), rng.randrange(B)) for _ in range(ztp(rng, mu_true))]
            edges = []; r_att = 0; rels = 0; solved = False
            while not solved and rels < 16 * B:
                r_att += geom(rng, q)
                edges.append(draw_legs(rng, B)); rels += 1
                if rels % check: continue
                det, _ = determined_set(B, edges)
                solved = any(det[i] and det[j] for i, j in stored)
                if not solved and rels % (4 * B) == 0:
                    t_att += 1
                    stored.extend((rng.randrange(B), rng.randrange(B)) for _ in range(poisson(rng, mu_true)))
            out.append((L, t_att + r_att, solved, rels))
    return out

# ---- observables and text-level rules ------------------------------------------
def am_obs(shared, w, B, mu, per_t, cells):
    kp, ap = k_pred(B, mu), a_pred(mu)
    units = [u * w for (_, u) in per_t]
    pbar = sum(units) / len(units)
    cost = {}
    for L in cells:
        cost[L] = (shared + sum(u * w for (LL, u) in per_t if LL == L)) / L
    sh = lsq_slope([math.log2(L) for L in cells], [math.log2(cost[L]) for L in cells])
    return {"KR": (shared / pbar) / kp, "FR": pbar / (ap * w), "d_sigma": sh - sig_pred(kp, cells),
            "pbar": pbar, "cost": cost}

def side(v, lo, hi, low_when_below):
    if lo <= v <= hi: return "pass"
    below = v < lo
    return "low" if below == low_when_below else "high"

def text_tests(v, zn=None):
    B, mu, n_t = v["B"], v["mu"], v["n_t"]
    bd = bands(B, mu, n_t)
    t = {}
    h = Z_DELTA * S_DELTA / math.sqrt(B)
    t["T_delta"] = side(v["delta_hat"], DELTA_INF - h, DELTA_INF + h, True)
    d2 = v["delta_hat"] ** 2
    tu = Z_U * math.sqrt(d2 * (1 - d2) / v["n_dec"]) if v["n_dec"] else 0.0
    t["T_u"] = side(v["u_hat"] - d2, -tu, tu, True)
    p = 1.0 - math.exp(-mu * v["u_hat"])
    if p > 0:
        ta = Z_A * math.sqrt(1 - p) / p / math.sqrt(n_t)
        t["T_a"] = side(v["a_bar"] - 1.0 / p, -ta, ta, False)
    else:
        t["T_a"] = "low"
    t["AM1_KR"] = side(v["KR"], bd["KR"][0], bd["KR"][1], True)
    t["AM2_FR"] = side(v["FR"], bd["FR"][0], bd["FR"][1], False)
    t["AM3_dsigma"] = side(v["d_sigma"], -DSIG, DSIG, False)
    if zn is not None:
        def var(x):
            return x["u_hat"] * (1 - x["u_hat"]) / x["n_dec"] + (2 * x["delta_hat"] * S_DELTA / math.sqrt(x["B"])) ** 2
        tc = Z_CMP * math.sqrt(var(v) + var(zn))
        t["T_cmp"] = side(v["u_hat"] - zn["u_hat"], -tc, tc, True)
    return t

def text_class(t):
    fails = {k: s for k, s in t.items() if s != "pass"}
    if not fails: return "PASS"
    if all(s == "low" for s in fails.values()):
        return "LOW-COV" if any(k in ("T_delta", "T_u", "T_cmp") for k in fails) else "LOW-RETRY"
    if all(s == "high" for s in fails.values()): return "HIGH"
    return "SPLIT"

def text_null_discriminates(nobs, bd):
    return (not (bd["KR"][0] <= nobs["KR"] <= bd["KR"][1]) and not (bd["FR"][0] <= nobs["FR"] <= bd["FR"][1])
            and not (-DSIG <= nobs["d_sigma"] <= DSIG) and nobs["KR"] < 0.125)

def text_yield(v):
    kp = 1 - math.exp(-v["mu"])
    z = (v["kappa_hat"] - kp) / math.sqrt(kp * (1 - kp) / v["n_att"])
    return z, z <= -Z_YIELD

def values_for_committed(arm, obs):
    """the dict layout binstd_core.gate_tests / yield_audit read"""
    return {"B": arm["B"], "mu": arm["mu"], "delta_hat": arm["delta_hat"], "u_hat": arm["u_hat"],
            "n_dec": arm["n_dec"], "n_t": arm["n_t"], "n_att": arm["n_att"], "a_bar": arm["a_bar"],
            "kappa_hat": arm["kappa_hat"], "rho_rel": arm["rel_att"] * (1 - math.exp(-arm["mu"])) / arm["B"],
            "KR": obs["KR"], "FR": obs["FR"], "d_sigma": obs["d_sigma"]}

# ---- incremental parity union-find for the null arm (own implementation) ------
class ParityUF:
    def __init__(self, B):
        self.p = list(range(B)); self.r = [0] * B; self.par = [0] * B; self.bad = [False] * B
    def find(self, x):
        path = []
        while self.p[x] != x:
            path.append(x); x = self.p[x]
        root = x
        # compress: accumulate parity from node to root
        acc = 0
        for v in reversed(path):
            acc ^= self.par[v]
            self.par[v] = acc
            self.p[v] = root
        return root
    def parity(self, x):
        self.find(x); return self.par[x] if self.p[x] != x else 0
    def add(self, i, s, k, t):
        if i == k:
            if s == t: self.bad[self.find(i)] = True
            return
        e = 0 if (-s * t) == 1 else 1
        ri, rk = self.find(i), self.find(k)
        pi, pk = (self.par[i] if i != ri else 0), (self.par[k] if k != rk else 0)
        if ri == rk:
            if (pi ^ pk) != e: self.bad[ri] = True
            return
        if self.r[ri] < self.r[rk]: ri, rk, pi, pk = rk, ri, pk, pi
        self.p[rk] = ri; self.par[rk] = pi ^ pk ^ e
        if self.r[ri] == self.r[rk]: self.r[ri] += 1
        self.bad[ri] = self.bad[ri] or self.bad[rk]
    def det(self, x): return self.bad[self.find(x)]

def null_arm_fast(rng, B, mu_c, f=1.0):
    mu_true = f * mu_c
    q = 1.0 - math.exp(-mu_true)
    check = max(1, B // 16)
    out = []
    for L in L_NULL:
        for _ in range(L):
            t_att = geom(rng, q)
            stored = [(rng.randrange(B), rng.randrange(B)) for _ in range(ztp(rng, mu_true))]
            uf = ParityUF(B); r_att = 0; rels = 0; solved = False
            while not solved and rels < 16 * B:
                r_att += geom(rng, q)
                uf.add(*draw_legs(rng, B)); rels += 1
                if rels % check: continue
                solved = any(uf.det(i) and uf.det(j) for i, j in stored)
                if not solved and rels % (4 * B) == 0:
                    t_att += 1
                    stored.extend((rng.randrange(B), rng.randrange(B)) for _ in range(poisson(rng, mu_true)))
            out.append((L, t_att + r_att, solved, rels))
    return out

