"""C08 + C09 (abstract model, synthetic; no group/oracle/cell).
C08 LOW-RETRY mapping: decomposition counts with the SAME mean mu but coverage
P(D>=1) = kr * (1 - exp(-mu)) (kr < 1: KN-FIND-007 direction, repeated sums;
kr > 1: Sidon-like excess), D | D>=1 = 1 + Poisson(mu / kappa' - 1); legs uniform.
Both binary cells carry the same kr; CTRL-ZN nominal; classes, deficit flags and
the H1 axis by the committed classifiers (dry calls).
C09 coset factor: the binary cells' true mean decomposition count over G is
f * mu_c (D-15) while every prediction uses mu_c. usage: SEED REPS"""
import json, math, os, random, sys
from multiprocessing import Pool
SCR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(SCR, "impl")); sys.path.insert(0, SCR)
import rt_model as rm, binstd_core as bc
MUZ = bc.MU_ZN_DESIGN

def cell(rng, B, mu, zv, f=1.0, kr=None):
    deficit = None
    if kr is not None:
        kp = kr * (1 - math.exp(-mu)); deficit = (kp, mu / kp - 1.0)
    arm = rm.reuse_arm(rng, B, mu, f=f, deficit=deficit)
    obs = rm.am_obs(arm["rel_att"], 1, B, mu, arm["per_t"], rm.L_IC)
    v = rm.values_for_committed(arm, obs)
    t = bc.gate_tests(v, zv)
    return bc.classify_cell(t), bc.yield_audit(v), t, v

def work(args):
    kind, par, reps, seed = args
    rng = random.Random(seed); cls = {}; ax = {}; zsum = 0.0; tf = {}
    for _ in range(reps):
        za = rm.reuse_arm(rng, 128, MUZ)
        zo = rm.am_obs(za["rel_att"], 1, 128, MUZ, za["per_t"], rm.L_IC)
        zv = rm.values_for_committed(za, zo)
        if bc.classify_cell(bc.gate_tests(zv)) != "PASS":
            continue                      # condition on G1 (a); rare
        phi, dfc = {}, {}
        for name in bc.BINARY_CELLS:
            if kind == "deficit":
                c, ya, t, v = cell(rng, 512, 1.0, zv, kr=par)
            else:
                c, ya, t, v = cell(rng, 512, 1.0, zv, f=par)
            phi[name] = c; dfc[name] = ya["coverage_deficit"]; zsum += ya["z"]
            cls[c] = cls.get(c, 0) + 1
            for k, s in t.items():
                if s != "pass": tf[k + ":" + s] = tf.get(k + ":" + s, 0) + 1
        a = bc.h1_axis(phi, {}, False, dfc); ax[a] = ax.get(a, 0) + 1
    return cls, ax, zsum, tf

if __name__ == "__main__":
    seed, reps = int(sys.argv[1]), int(sys.argv[2])
    jobs = []
    for kr in (1.0, 0.98, 0.95, 0.9, 0.85, 0.8, 0.7, 1.05, 1.1, 1.2):
        jobs.append(("deficit", kr, reps, seed + int(kr * 1000)))
    for f in (1.0, 1.005, 1.01, 1.02, 1.05, 1.1, 1.2):
        jobs.append(("coset", f, reps, seed + 5000 + int(f * 1000)))
    with Pool(4) as pool:
        out = pool.map(work, jobs)
    res = {"seed_base": seed, "reps_per_point": reps, "cells_per_rep": 2, "model": __doc__.split("usage")[0]}
    for (kind, par, r, s), (cls, ax, zsum, tf) in zip(jobs, out):
        n = sum(ax.values())
        res.setdefault(kind, {})[str(par)] = {
            "seed": s, "reps_G1a_passing": n,
            "class_rate_per_cell": {k: v / (2 * n) for k, v in sorted(cls.items())},
            "H1_axis": {k: v / n for k, v in sorted(ax.items())},
            "mean_kappa_z": zsum / (2 * n),
            "test_fail_rate_per_cell": {k: round(v / (2 * n), 5) for k, v in sorted(tf.items())}}
    print(json.dumps(res, indent=1, sort_keys=True))

"""C10: PTM-A to PTM-D against the plan's failure_signature. Own implementation of
model M_m (mpmath, 50 digits) from the definitions text, cross-checked by dry
calls of committed stage0.py and binstd_core.py pure functions. Synthetic cost
tables and generative values only; no group, oracle, curve or declared cell."""
import json, math, os, sys
import mpmath as mp
mp.mp.dps = 50
SCR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(SCR, "impl")); sys.path.insert(0, SCR)
import stage0 as s0, binstd_core as bc
r = mp.mpf(680564733841876926932320129493409985129)
L2 = lambda x: mp.log(x, 2)
Np = r / 262; l2Np = L2(Np); rho = mp.sqrt(mp.pi * r / (4 * 131))
def bcap(m): return mp.power(mp.factorial(m) * mp.power(2, 131), mp.mpf(1) / m)
def mu(m, B): return B ** m / (mp.factorial(m) * mp.power(2, 131))
def A(x): return 1 / (1 - mp.exp(-x))
def retry(m): return 1 / (1 - m * mp.exp(-m))
def terms(m, B, C, k=1):
    a_ = A(mu(m, B)); return B * a_ * C + k * m * B * B, a_ * retry(m) * C   # T_shared, per_target
def window(m, B, C, c=1):
    Ts, pt = terms(m, B, C); a = pt / (c * rho); b = Ts / (c * rho)
    if 4 * a * b >= 1: return None
    sq = mp.sqrt(1 - 4 * a * b)
    return [float(2 * L2(2 * b / (1 + sq))), float(2 * L2((1 + sq) / (2 * a)))]
res = {}
# ---------------- PTM-A ---------------------------------------------------------
pa = {}
for m in (4, 5, 6, 8, 16):
    B = bcap(m); Tg = mp.sqrt(Np / B); Pg = mp.sqrt(Np * B)
    Ts, pt = terms(m, B, Tg)
    row = {"log2_P_IC_over_P_gen": float(L2(Ts / Pg)), "log2_online_over_T_gen": float(L2(pt / Tg)),
           "log2_S_T2_over_Nprime_online": float(L2(B * pt * pt / Np)),
           "log2_PT_plus_T2_over_Nprime": float(L2((Ts * pt + pt * pt) / Np)),
           "identity_log2_Bcap_Tgen_minus_Pgen": float(L2(B * Tg) - L2(Pg))}
    for c in (1, 1.128, 2.15, 2.36):
        row["window_at_C_eq_T_gen_c%s" % c] = window(m, B, Tg, c)
    pa[str(m)] = row
# the m = 4 envelope at C = T_gen(4): which committed-range bases open a window
Tg4 = mp.sqrt(Np / bcap(4)); env = {}
for c in (1, 1.128, 1.66, 2.0, 2.15, 2.36):
    opened = [float(mp.mpf("29.036035") + mp.mpf("0.01") * i) for i in range(697)
              if window(4, mp.power(2, mp.mpf("29.036035") + mp.mpf("0.01") * i), Tg4, c) is not None]
    env[str(c)] = {"bases_with_window": len(opened), "log2_B_range": [min(opened), max(opened)] if opened else None}
# the own-advice frontier oracle C = T_gen(B) at every base of the committed range
own = {}
for c in (1, 1.128, 1.5, 1.66, 1.7, 2.0):
    opened = []
    for i in range(697):
        xb = mp.mpf("29.036035") + mp.mpf("0.01") * i; B = mp.power(2, xb)
        if window(4, B, mp.sqrt(Np / B), c) is not None: opened.append(float(xb))
    own[str(c)] = {"bases_with_window": len(opened), "log2_B_range": [min(opened), max(opened)] if opened else None}
res["PTM-A"] = {"at_B_cap": pa, "m4_envelope_oracle_at_T_gen4": env,
                "m4_range_oracle_on_own_advice_frontier_C_eq_sqrt_Nprime_over_B": own}
# ---------------- PTM-B ---------------------------------------------------------
def ic1(m, xB, xC):
    B = mp.power(2, xB); Ts, pt = terms(m, B, mp.power(2, xC)); return float(L2((Ts + pt) / rho))
def tie(m, xB):
    B = mp.power(2, xB); a_ = A(mu(m, B))
    # IC(1) = rho:  B A C + m B^2 + A retry C = rho  ->  C = (rho - m B^2) / (A (B + retry))
    return float(L2((rho - m * B * B) / (a_ * (B + retry(m)))))
xsub, x5 = mp.mpf("29.036035"), L2(bcap(5))
pb = {"m4_subcap": {"log2_IC1_over_rho_at_D3_4": ic1(4, xsub, mp.mpf("11.010251")),
                    "tie_budget": tie(4, xsub), "tie_minus_D3_4": tie(4, xsub) - 11.010251,
                    "g0_window": window(4, mp.power(2, xsub), mp.power(2, mp.mpf("11.010251"))),
                    "tie_rule_reads_tie": abs(window(4, mp.power(2, xsub), mp.power(2, mp.mpf("11.010251")))[0]) < 1e-4,
                    "perturbed_C_plus_0.01_log2_IC1_over_rho": ic1(4, xsub, mp.mpf("11.020251")),
                    "perturbed_B_plus_0.01_log2_IC1_over_rho": ic1(4, xsub + mp.mpf("0.01"), mp.mpf("11.010251"))},
      "m5_Bcap": {"log2_IC1_over_rho_at_D3_5": ic1(5, x5, mp.mpf("33.075936")),
                  "log2_IC1_over_rho_at_prop": ic1(5, x5, mp.mpf("32.414212")),
                  "tie_budget": tie(5, x5), "tie_minus_D3_5": tie(5, x5) - 33.075936,
                  "stated_difference_minus_log2_A1": float(-L2(A(1))),
                  "g0_window_D3": window(5, bcap(5), mp.power(2, mp.mpf("33.075936"))),
                  "g0_window_prop": window(5, bcap(5), mp.power(2, mp.mpf("32.414212")))},
      "stage0_dry": {"m4_ic1": s0.ic1_over_rho(4, s0.X_SUB, s0.D3_4), "m4_tie": s0.tie_budget(4, s0.X_SUB),
                     "m5_ic1_D3": s0.ic1_over_rho(5, s0.bcap(5), s0.D3_5), "m5_tie": s0.tie_budget(5, s0.bcap(5)),
                     "m4_ic1_C_plus_0.01": s0.ic1_over_rho(4, s0.X_SUB, s0.D3_4 + 0.01)}}
res["PTM-B"] = pb
# ---------------- PTM-C ---------------------------------------------------------
pc = {"m5_window_g": {}}
for g in (12, 13, 13.2, 14):
    pc["m5_window_g"][str(g)] = {"D3": window(5, bcap(5), mp.power(2, 33.075936 + g)),
                                 "proposal": window(5, bcap(5), mp.power(2, 32.414212 + g)),
                                 "stage0_D3": s0.win(5, s0.bcap(5), s0.D3_5 + g),
                                 "stage0_prop": s0.win(5, s0.bcap(5), s0.PROP_5 + g)}
# identical predictions at matched (B, mu): the prediction functions take no cell argument
import inspect
pc["prediction_function_signatures"] = {f: str(inspect.signature(getattr(bc, f))) for f in
                                        ("a_pred", "k_pred", "am_bands", "sigma_pred", "gate_tests", "yield_audit")}
v = bc.gen_values(512, 1.0)
pc["same_values_same_tests_any_label"] = bc.gate_tests(v, bc.gen_values(128, bc.MU_ZN_DESIGN))
res["PTM-C"] = pc
# ---------------- PTM-D ---------------------------------------------------------
pdd = {}
for name, (B, mu_) in (("CTRL-ZN", (128, bc.MU_ZN_DESIGN)), ("BIN-ORD-19", (512, 1.0))):
    bands = bc.am_bands(B, mu_, 1365)
    rows = {}
    for q in (0.05, 0.1, 0.5, 0.93, 1.0, 1.03, 2.0, 16.0):      # null per-target units / shared units
        nl = bc.gen_null(B, mu_, q_null=q)
        f, disc = bc.null_check(nl, bands)
        rows[str(q)] = {"KR": nl["KR"], "FR": nl["FR"], "d_sigma": nl["d_sigma"], "discriminates": disc}
    qmin = 8.0 / bc.k_pred(B, mu_)
    pdd[name] = {"null_by_q": rows, "q_below_which_KR_ge_0.125": qmin}
# counterfactual: the no-reuse null fed AS the reuse arm (attempt-equivalent units q*K_pred per target)
cf = {}
zn = bc.gen_values(128, bc.MU_ZN_DESIGN)
for label, kw in (("P8_as_declared", dict(a_ratio=381.2)),
                  ("null_as_reuse_q0.93", dict(a_ratio=0.93 * 380.70)),
                  ("null_as_reuse_u1", dict(a_ratio=0.93 * 380.70 * (1 - math.exp(-1.0 * bc.u_pred())) / (1 - math.exp(-1.0)), u=1.0))):
    vv = bc.gen_values(512, 1.0, **kw)
    t = bc.gate_tests(vv, zn); c = bc.classify_cell(t)
    cf[label] = {"tests": t, "class": c, "pair_axis": bc.h1_axis({bc.ORD_CELL: c, bc.KOB_CELL: c}, {}, False,
                                                                   {bc.ORD_CELL: False, bc.KOB_CELL: False})}
pdd["counterfactual_null_as_reuse_arm"] = cf
res["PTM-D"] = pdd
print(json.dumps(res, indent=1, sort_keys=True, default=str))

