"""C12: reachability of H1-NEGATIVE-COVERAGE from generative quantities: an oracle
whose relation phase returns, with probability d, a DUPLICATE of an earlier kept
relation (a coverage-limited relation set: fewer distinct edges, lower determined
fraction); target legs uniform and independent. Abstract, synthetic, seed 810095012.
Classified by the committed classifiers (dry calls)."""
import json, math, os, random, sys
SCR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(SCR, "impl")); sys.path.insert(0, SCR)
import rt_model as rm, binstd_core as bc
rng = random.Random(810095012); MUZ = bc.MU_ZN_DESIGN
def dup_arm(B, mu, d):
    q = 1 - math.exp(-mu); rel_att = 0; edges = []
    for _ in range(B):
        rel_att += rm.geom(rng, q)
        edges.append(rng.choice(edges) if (edges and rng.random() < d) else rm.draw_legs(rng, B))
    det, _ = rm.determined_set(B, edges)
    per_t = []; nd = nu = na = nn = 0
    for L in rm.L_IC:
        for _ in range(L):
            a = 0
            while True:
                a += rm.geom(rng, q); nn += 1; D = rm.ztp(rng, mu); nd += D; uu = 0
                for _d in range(D):
                    i, s, k, t = rm.draw_legs(rng, B)
                    if det[i] and det[k]: uu += 1
                nu += uu
                if uu: break
            per_t.append((L, a)); na += a
    arm = {"B": B, "mu": mu, "rel_att": rel_att, "delta_hat": sum(det) / B, "u_hat": nu / nd, "n_dec": nd,
           "n_att": na, "n_t": rm.N_T, "a_bar": na / rm.N_T, "kappa_hat": nn / na}
    return rm.values_for_committed(arm, rm.am_obs(rel_att, 1, B, mu, per_t, rm.L_IC))
out = {}
for d in (0.1, 0.2, 0.3):
    ax = {}
    for _ in range(150):
        za = rm.reuse_arm(rng, 128, MUZ)
        zv = rm.values_for_committed(za, rm.am_obs(za["rel_att"], 1, 128, MUZ, za["per_t"], rm.L_IC))
        phi = {n: bc.classify_cell(bc.gate_tests(dup_arm(512, 1.0, d), zv)) for n in bc.BINARY_CELLS}
        a = bc.h1_axis(phi, {}, False, {n: False for n in bc.BINARY_CELLS}); ax[a] = ax.get(a, 0) + 1
    out[str(d)] = {k: v / 150 for k, v in sorted(ax.items())}
print(json.dumps({"seed": 810095012, "reps": 150, "duplicate_prob_to_H1_axis": out}, sort_keys=True))

"""C14: minimal text extraction from the three retrieved PDFs (zlib-inflate every
FlateDecode stream; collect strings of Tj / TJ operators; join). Used only to
locate the statements the contract cites; output is lossy (ligatures, math)."""
import re, sys, zlib, os
def extract(path):
    data = open(path, "rb").read(); out = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end(); end = data.find(b"endstream", start)
        if end < 0: continue
        raw = data[start:end]
        try: dec = zlib.decompress(raw)
        except Exception:
            try: dec = zlib.decompressobj().decompress(raw)
            except Exception: continue
        if b"Tj" not in dec and b"TJ" not in dec: continue
        page = []
        for tm in re.finditer(rb"\[(.*?)\]\s*TJ|\((.*?)\)\s*Tj|(T\*|Td|TD|Tm)", dec, re.S):
            if tm.group(1) is not None:
                parts = re.findall(rb"\(((?:\\.|[^\\)])*)\)|(-?\d+\.?\d*)", tm.group(1))
                s = b""
                for p, num in parts:
                    if p: s += p
                    elif num and float(num) < -200: s += b" "
                page.append(s)
            elif tm.group(2) is not None: page.append(tm.group(2))
            else: page.append(b" ")
        txt = b"".join(page)
        txt = re.sub(rb"\\([()\\])", rb"\1", txt)
        out.append(txt.decode("latin-1"))
    return "\n".join(out)
if __name__ == "__main__":
    t = extract(sys.argv[1]); pats = sys.argv[2:]
    t1 = re.sub(r"\s+", " ", t)
    for p in pats:
        for mm in list(re.finditer(p, t1))[:4]:
            print("[%s] ...%s..." % (p, t1[max(0, mm.start() - 160): mm.end() + 260]))
            print()

