"""C14b: PDF text decode with ToUnicode CMaps (for the Kuhn-Struik PDF, whose
fonts use custom encodings). Objects parsed by regex; streams filtered by
ASCII85Decode/FlateDecode; page /Font resources resolved to ToUnicode maps."""
import re, sys, zlib, base64
d = open(sys.argv[1], "rb").read()
objs = {}
for m in re.finditer(rb"(\d+)\s+0\s+obj(.*?)endobj", d, re.S):
    objs[int(m.group(1))] = m.group(2)
def stream_of(body):
    m = re.search(rb"stream\r?\n(.*?)endstream", body, re.S)
    if not m: return None
    raw = m.group(1); head = body[:m.start()]
    filt = re.findall(rb"/(ASCII85Decode|FlateDecode)", head)
    for f in filt:
        if f == b"ASCII85Decode":
            s = raw.strip()
            if s.startswith(b"<~"): s = s[2:]
            if s.endswith(b"~>"): s = s[:-2]
            raw = base64.a85decode(s.replace(b"\r", b"").replace(b"\n", b""), adobe=False)
        else:
            try: raw = zlib.decompress(raw)
            except Exception: raw = zlib.decompressobj().decompress(raw)
    return raw
def cmap(objnum):
    s = stream_of(objs[objnum]) or b""; mp = {}
    for blk in re.findall(rb"beginbfchar(.*?)endbfchar", s, re.S):
        for a, b in re.findall(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            mp[int(a, 16)] = bytes.fromhex(b.decode()).decode("utf-16-be", "replace")
    for blk in re.findall(rb"beginbfrange(.*?)endbfrange", s, re.S):
        for a, b, c in re.findall(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", blk):
            lo, hi, st = int(a, 16), int(b, 16), int(c, 16)
            for k in range(lo, hi + 1): mp[k] = chr(st + k - lo)
    return mp
fontmap = {}
for n, body in objs.items():
    if re.search(rb"/Type\s*/Font", body):
        m = re.search(rb"/ToUnicode\s+(\d+)\s+0\s+R", body)
        fontmap[n] = cmap(int(m.group(1))) if m else {}
def res_fonts(body):
    m = re.search(rb"/Font\s*<<(.*?)>>", body, re.S)
    if not m:
        m2 = re.search(rb"/Font\s+(\d+)\s+0\s+R", body)
        if m2: return res_fonts(b"/Font <<" + objs[int(m2.group(1))].split(b"<<", 1)[1])
        return {}
    return {k: int(v) for k, v in re.findall(rb"/(\w+)\s+(\d+)\s+0\s+R", m.group(1))}
out = []
for n, body in sorted(objs.items()):
    if not re.search(rb"/Type\s*/Page\b", body): continue
    rm = re.search(rb"/Resources\s+(\d+)\s+0\s+R", body)
    rbody = objs[int(rm.group(1))] if rm else body
    fonts = res_fonts(rbody)
    cs = re.findall(rb"/Contents\s+(\d+)\s+0\s+R", body) or []
    arr = re.search(rb"/Contents\s*\[(.*?)\]", body, re.S)
    if arr: cs = re.findall(rb"(\d+)\s+0\s+R", arr.group(1))
    cur = {}; txt = []
    for c in cs:
        s = stream_of(objs[int(c)]) or b""
        for tok in re.finditer(rb"/(\w+)\s+[\d.]+\s+Tf|\[(.*?)\]\s*TJ|\(((?:\\.|[^\\)])*)\)\s*Tj|(T\*|Td|TD|Tm|')", s, re.S):
            if tok.group(1):
                cur = fontmap.get(fonts.get(tok.group(1).decode(), -1), {})
            elif tok.group(2) is not None or tok.group(3) is not None:
                if tok.group(2) is not None:
                    parts = re.findall(rb"\(((?:\\.|[^\\)])*)\)|(-?\d+\.?\d*)", tok.group(2))
                else:
                    parts = [(tok.group(3), b"")]
                for p, num in parts:
                    if p:
                        p = re.sub(rb"\\(\d{1,3})", lambda m: bytes([int(m.group(1), 8)]), p)
                        p = re.sub(rb"\\(.)", rb"\1", p)
                        txt.append("".join(cur.get(b, chr(b)) for b in p))
                    elif num and float(num) < -200: txt.append(" ")
            else: txt.append(" ")
    out.append("".join(txt))
t = re.sub(r"\s+", " ", "\n".join(out))
open(sys.argv[1] + ".cmap.txt", "w").write(t)
for p in sys.argv[2:]:
    for mm in list(re.finditer(p, t))[:3]:
        print("[%s] ...%s..." % (p, t[max(0, mm.start() - 300): mm.end() + 700])); print()
